import { Component } from 'react'
import PropTypes from 'prop-types'
import { replace } from 'lodash/string'
import FullPageModal from '../../../../../components/FullPageModal'
import { SuccessStatusWrapper } from './index.style'
import { VERIFY_EMAIL_SUCCESS, CIRCLE_THUMB_WHITE } from '../../../../../images'
import { CustomText, Button } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang'
import { ONE_POINT_RP } from '../../../../../constants/payment'

class PointConvertsSuccess extends Component {
  static propTypes = {
    showModal: PropTypes.bool,
    onCloseModal: PropTypes.func,
    points: PropTypes.number,
    history: PropTypes.func
  }

  handleBackToHome = () => {
    // this is go back to wallet screen
    this.props.history.push('/balance')
    this.props.onCloseModal()
  }

  getPointTransferMsg = () => {
    const { points } = this.props
    const msg = LANG_STRINGS.pointsTransaferMsg
    return replace(msg, 'XXXX', points * ONE_POINT_RP)
  }

  render () {
    const { showModal } = this.props
    return (
      <FullPageModal
        onCloseModal={this.handleBackToHome}
        showModal={showModal}
        isImgHeader
      >
        <SuccessStatusWrapper bgUrl={VERIFY_EMAIL_SUCCESS}>
          <div className='content'>
            <img alt='payment-icon' src={CIRCLE_THUMB_WHITE} className='payment-icon' />
            <div className='content-text'>
              <CustomText weight={800} size='20px' textAlign='center' bottom='20px'>
                {LANG_STRINGS.transferSuccessful}
              </CustomText>
              <CustomText size='14px' textAlign='center' bottom='2px'>
                {this.getPointTransferMsg()}
              </CustomText>
            </div>
            <Button className='resend-button' onClick={this.handleBackToHome}>
              {LANG_STRINGS.myBonusBalance}
            </Button>
          </div>
        </SuccessStatusWrapper>
      </FullPageModal>
    )
  }
}

export default PointConvertsSuccess
