import { createRef, Component } from 'react'
import { connect } from 'react-redux'
import { NotificationContainer, NotificationManager } from 'react-notifications'
import transactionAction from '../../../../../redux/transaction/action'
import { Container, CustomText, Button } from '../../../../../components'
import { LANG_STRINGS, ERROR_LANG } from '../../../../../lang'
import { PointConvertStyle, DisplayMyPoint } from './index.style'
import { YELLOW_REACT_POLYGON } from '../../../../../images'
import { formatMoney, convertTo3digitFloat } from '../../../../../helpers/utility'
import Slider from '../../../../../components/Slider'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { Row, DisplayFlexCCC } from '../../../../../commonStyle/index.style'
import NumberFormat from 'react-number-format'
import PointConvertsSuccess from '../../components/PointConvertsSuccess'

const { convertPointsRequest, resetTransactionRequest } = transactionAction

class PointConvertPage extends Component {
  constructor (props) {
    super(props)
    this.state = {
      points: 0,
      showModal: false
    }
    this.sliderRef = createRef()
  }

  componentWillReceiveProps (nextProps) {
    const { pointConvertStatus, pointsError, resetTransactionRequest } = nextProps

    if (pointsError && pointConvertStatus && pointConvertStatus !== 'success') {
      if (typeof pointConvertStatus === 'object') {
        NotificationManager.error(pointConvertStatus.point[0])
      } else {
        NotificationManager.error(pointConvertStatus)
      }

      resetTransactionRequest(['pointConvertStatus'])
    }

    if (pointConvertStatus === 'success') {
      this.setState({
        showModal: true
      })
    }
  }

  handleConvertPoint = () => {
    // call api to convert this point
    this.props.convertPointsRequest({
      point: convertTo3digitFloat(this.state.points)
    })
  }

  handleSliderChange = (value) => {
    this.setState({
      points: convertTo3digitFloat(value)
    })
  }

  handleCloseModal = () => {
    this.setState({
      showModal: false
    })
  }

  handleValueChange = (values, isUpdated) => {
    const { value } = values
    const points = convertTo3digitFloat(value || 0)
    const { agentDetails = {} } = this.props
    if (value > agentDetails.point_balance) {
      return value ? NotificationManager.error(ERROR_LANG.pointBalanceInsufficient) : null
    }
    this.setState({
      points
    })
    const sliderRef = this.sliderRef.current
    sliderRef.updateSliderValue(points)
  }

  getSliderMinMaxText = (title) => {
    return (
      <CustomText
        size='14px;'
        color={AgentColorPallette.black}
        top='10px'
        bottom='10px'
      >
        {title}
      </CustomText>
    )
  }

  render () {
    const { pointsLoading, agentDetails = {} } = this.props

    return (
      <Container
        title={LANG_STRINGS.convertPoint}
        loader={pointsLoading}
        displayBackButton
      >
        <PointConvertStyle>
          <div>
            <DisplayMyPoint>
              <CustomText
                weight={800}
                top='20px'
              >
                {LANG_STRINGS.myTotalPoint}
              </CustomText>
              <CustomText
                size='20px'
                weight={800}
                bottom='20px'
              >
                {formatMoney(agentDetails.point_balance, 3, '')}
              </CustomText>
            </DisplayMyPoint>
            <img className='polygon-img' src={YELLOW_REACT_POLYGON} alt='' />
          </div>
          <div className='point-slider-container'>
            <Row className='points-input-container' align='center' justify='space-between'>
              <CustomText
                color={AgentColorPallette.black}
                size='14px'
              >
                {LANG_STRINGS.enterPoints}
              </CustomText>
              <NumberFormat
                decimalScale={3}
                className='points-input'
                disabled={!agentDetails.point_balance}
                value={this.state.points || ''}
                onValueChange={(data) => this.handleValueChange(data, true)}
                placeholder={LANG_STRINGS.enterPoints}
              />
            </Row>
            <Slider
              name='points'
              max={agentDetails.point_balance}
              ref={this.sliderRef}
              disabled={!agentDetails.point_balance}
              onChange={value => this.handleSliderChange(value)}
            />
            <Row justify='space-between'>
              {this.getSliderMinMaxText(0)}
              {this.getSliderMinMaxText(formatMoney(agentDetails.point_balance, 3, ''))}
            </Row>
            <CustomText
              size='14px'
              top='10px'
              color={AgentColorPallette.black}
            >
              *1 Poin = Rp 1.000
            </CustomText>
          </div>
          <DisplayFlexCCC>
            <Button
              className='convert-point-btn'
              onClick={this.handleConvertPoint}
              disabled={!agentDetails.point_balance || !this.state.points}
            >
              {LANG_STRINGS.convertPoint}
            </Button>
          </DisplayFlexCCC>
        </PointConvertStyle>
        <PointConvertsSuccess
          showModal={this.state.showModal}
          history={this.props.history}
          points={this.state.points}
          onCloseModal={this.handleCloseModal}
        />
        <NotificationContainer />
      </Container>
    )
  }
}

export default connect(
  (state) => ({
    agentDetails: state.User.agentDetails,
    pointsLoading: state.Loading.CONVERT_POINTS,
    pointsError: state.Error.CONVERT_POINTS,
    pointConvertStatus: state.Transaction.pointConvertStatus
  }),
  {
    convertPointsRequest,
    resetTransactionRequest
  }
)(PointConvertPage)
